/** @summary Require actual native behavior. @param value Observation. @param message Fixed failure diagnostic. */
void Check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
/** @summary Poll a stateful observation once per bounded iteration. @param predicate Observation. @param message Failure evidence. */
template<class F> void Await(F predicate,const char* message){const auto end=std::chrono::steady_clock::now()+5s;bool done=predicate();while(!done&&std::chrono::steady_clock::now()<end){std::this_thread::sleep_for(1ms);done=predicate();}Check(done,message);}
/** @summary Bound one actual native producer/destructor pause. */
struct Gate final{
    std::mutex mutex;std::condition_variable changed;bool entered{},released{};
    /** @summary Release native participant on stack unwinding. */
    ~Gate(){Release();}
    /** @summary Pause the first invocation outside Q. */
    void Pause(){std::unique_lock lock(mutex);if(entered)return;entered=true;changed.notify_all();if(!changed.wait_for(lock,5s,[&]{return released;}))throw std::runtime_error("scope native pause timeout");}
    /** @summary Require actual native entry. */
    void Wait(){std::unique_lock lock(mutex);Check(changed.wait_for(lock,5s,[&]{return entered;}),"actual native pause reached");}
    /** @summary Resume without changing resource ownership. */
    void Release(){std::lock_guard lock(mutex);released=true;changed.notify_all();}
};
